ALTER POLICY "members delete their spaces' accounts" ON "ledger_accounts" TO authenticated USING ("ledger_accounts"."space_id" = any (array(select public.my_space_ids())) and "ledger_accounts"."kind" = 'account');--> statement-breakpoint
